const __pageData = JSON.parse('{"title":"Go++ Source-Mapped Diagnostics Specification","description":"","frontmatter":{},"headers":[],"relativePath":"reference/specifications/compiler-diagnostics.md","filePath":"reference/specifications/compiler-diagnostics.md","lastUpdated":null}');
